    {
      "path": "js/src/dialog-base.ts",
      "sha256": "365b3e69778c2fdc18db529770b50c1881f0588747bead1c79c46c86f9ca9f1b",
      "before": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    if (preventBodyScroll) {
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }
  }",
      "after": "  protected _showElement({ modal = true, preventBodyScroll = true }: { modal?: boolean, preventBodyScroll?: boolean } = {}): void {
    this._openedAsModal = modal

    if (modal) {
      this._element.showModal()
    } else {
      this._element.show()
    }

    if (preventBodyScroll) {
      document.documentElement.classList.add(CLASS_NAME_OPEN)
    }

    // Move focus to the dialog or first focusable element
    const autofocus = this._element.querySelector('[autofocus]');
    if (autofocus) {
      autofocus.focus();
    } else {
      const focusableSelector = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
      const focusable = this._element.querySelector(focusableSelector);
      if (focusable) {
        focusable.focus();
      } else {
        this._element.focus();
      }
    }
  }"
    }
  ],
  "expected_accessibility_effect": "When the drawer opens, focus will be moved to the close button (or first focusable control), allowing users to tab to the In stock checkbox and activate the Show results button without needing a mouse.",
  "functional_risks": [
    "Changing focus behavior could interfere with pages that rely on focus remaining on the trigger element after opening a dialog.",
    "If the dialog contains no focusable elements, the fallback focuses the dialog itself (made focusable via script) or the button, which may cause unexpected focus movement.",
    "The focus adjustment runs for both modal and non-modal dialogs, which may alter existing behavior for non‑modal dialogs that intentionally do not move focus."
